          "operator": "IS_TRUE"
        }
      ]
    },
    "then": {
      "result": "APPLICABLE",
      "activate": [
        {
          "type": "SCREEN",
          "id": "imdg-control"
        },
        {
          "type": "CONTROL",
          "id": "CTRL-IMDG-DG"

},
        {
          "type": "EVIDENCE_POLICY",
          "id": "EVID-IMDG-MANIFEST-DECLARATION"
        }
      ],
      "stateEffect": "DG_CONTROL_REQUIRED",
      "reasonCode": "IMDG_42_24_ACTIVE"
    },
    "unknownPolicy": "REVIEW_REQUIRED",
    "priority": 700,
    "requiresHumanReview": false,
    "tags": [
      "IMDG",
      "SHIP",
      "CARGO"
    ],
