  $$("option",$("#modal")).forEach(o=>{if(!o.hasAttribute("value"))o.value=o.textContent;});
  $$(".field",$("#modal")).forEach((f,i)=>{const c=f.querySelector("input,select,textarea"), l=f.querySelector("label"); if(c&&l){if(!c.id)c.id="modal_field_"+i;l.htmlFor=c.id;if(l.textContent.includes("*"))c.required=true;}});
  const qty=$("#reqForm [name=qty]"), stock=$("#reqForm [name=stock]"); if(qty){qty.min="1";qty.step="1";} if(stock){stock.min="0";stock.step="1";}
  $("#modalBackdrop").classList.add("show");
}
function closeModal(){ $("#modalBackdrop").classList.remove("show"); }
