function applicabilityOutcome(){
 const mode=document.getElementById('appMode')?.value || (vessel().type.includes('Tug')?'TUG':'SHIP');
 const flag=document.getElementById('appFlag')?.value || 'TR';
 const type=document.getElementById('appType')?.value || (mode==='TUG'?'ASD_TUG':'OIL_TANKER');
 const job=document.getElementById('appJob')?.value || (mode==='TUG'?'HARBOUR_ASSIST':'NONE');
 const winch=document.getElementById('appWinch')?.value || 'YES';
 const m79=document.getElementById('appM79')?.value || 'YES';
 const msmd=document.getElementById('appMsmd')?.value || 'YES';
 const dg=document.getElementById('appDG')?.value || 'NO';
 const rows=[];
 const add=(id,result,reason,act)=>rows.push({id,result,reason,act});
 add('ISM §7', mode==='TUG'?'APPLICABLE':'APPLICABLE',

mode==='TUG'?P_L('Römorkör operasyon planı ve yürütme kontrolü aktif.','Tug operation planning and execution controls active.'):P_L('Gemi operasyon kontrolleri aktif.','Ship operation controls active.'), mode==='TUG'?'Towage Plan · Risk & Briefing · Execution':'Ship Operations · Departure · Voyage');
 if(mode==='TUG'){
   if(m79==='UNKNOWN' || winch==='UNKNOWN') add('IACS M79','REVIEW_REQUIRED',P_L('Class/winch girdisi belirsiz.','Class/winch input is uncertain.'),'Class review');
   else if(winch==='YES' && m79==='YES' && job!=='OCEAN_TOWAGE') add('IACS M79','APPLICABLE',P_L('Emergency release rule pack aktif.','Emergency release rule pack active.'),'ERS · Survey · Verification');
   else add('IACS M79','NOT_APPLICABLE',P_L('Predicate sağlanmadı veya solely ocean towage.','Predicate not met or solely ocean towage.'),'—');
   add('TR Tug MSMD', msmd==='UNKNOWN'?'REVIEW_REQUIRED':'APPLICABLE', msmd==='UNKNOWN'?P_L('Asgari Emniyet Belgesi doğrulaması gerekli.','Minimum Safe Manning document verification required.'):P_L('Römorkör minimum manning kontrolü aktif.','Tug minimum manning control active.'),'Crew Readiness · Safe Manning');
   add('TR Tug Service', flag==='TR'?'APPLICABLE':'NOT_APPLICABLE', flag==='TR'?P_L('Türkiye römorkörcülük service overlay değerlendirilir.','Turkish tug-service overlay is evaluated.'):P_L('Türk bayrak/service overlay uygulanmıyor.','Turkish flag/service overlay not applied.'),'BP · Class · Fire · Insurance');
   if(job==='OCEAN_TOWAGE') add('Ocean Towage Pack','APPLICABLE',P_L('Harbour pack yerine ocean towage suitability/class pack değerlendirilir.','Ocean towage suitability/class pack is evaluated instead of harbour pack.'),'Towage suitability · Certificates');
 } else {
   add('STCW V Tanker', ['OIL_TANKER','CHEMICAL_TANKER','GAS_CARRIER'].includes(type)?'APPLICABLE':'NOT_APPLICABLE', P_L('Gemi tipine göre özel eğitim/yeterlik kontrolü.','Special training/qualification check by vessel type.'),'Crew Certificates · Training Matrix');
   add('IMDG 42-24', dg==='UNKNOWN'?'REVIEW_REQUIRED':(dg==='YES'?'APPLICABLE':'NOT_APPLICABLE'), dg==='UNKNOWN'?P_L('Tehlikeli yük girdisi belirsiz.','Dangerous-goods input is uncertain.'):P_L('Paketli tehlikeli yük girdisine göre değerlendirme.','Evaluation based on packaged dangerous-goods input.'),'IMDG Control · Evidence');
 }
 return rows;
}
