 function targetLang(){return (state.lang||'tr').toLowerCase()==='en'?'en':'tr';}
 function translateText(text,lang=targetLang()){
   if(!text||!text.trim()) return text;
   for(const [en,tr] of UI_CONTROL_PAIRS){if(text.trim()===(lang==='tr'?en:tr))return text.replace(text.trim(),lang==='tr'?tr:en);}
   if(lang==='tr') text=text.replaceAll('Core Safety Operations','Temel Emniyet Operasyonları').replaceAll('PERSONELEL','PERSONEL');
   if(lang==='en') text=text.replaceAll('Rolee-first','Role-first').replaceAll('MOBILEEE','MOBILE');
   const lead=text.match(/^\s*/)?.[0]||'', tail=text.match(/\s*$/)?.[0]||'', core=text.trim();
   for(const [en,tr] of MERGED_PAIRS){
